// Фикстура интеграционного теста навигации ($.nav).
//
// Небольшая арена 640×480 с сеткой 32 px и стеной-перегородкой в колонке 10.
// В стене оставлены проходы сверху (ряды 0..2) и снизу (ряды 12..14), чтобы
// путь в обход был заведомо длиннее прямой. Герой стартует слева, «цель» —
// безтелесный узел справа: до неё можно дойти, но она не мешает физически.

$.ready(() => {
    $.world.gravity(0, 0).color('#0b1020');

    $.nav.clear();
    const grid = $.nav.grid({ x: 0, y: 0, w: 640, h: 480, cell: 32, diagonal: true });

    // Стена собрана из отдельных <wall>: так проверяется buildFromWalls,
    // который читает габариты узлов, а не только теги.
    for (let cy = 3; cy < 12; cy++) {
        $('<wall>', { class: 'blocker' })
            .at(10 * 32 + 16, cy * 32 + 16)
            .size(32, 32)
            .appendTo($.world);
    }
    // agentRadius — запас на габарит агента: герой 28×40, берём 20. Без него
    // сглаженный путь идёт вплотную к стене и тело в неё упирается.
    grid.buildFromWalls({ tags: ['wall'], inset: 0, agentRadius: 20 });
    globalThis.__grid = grid;

    $('<npc>', { id: 'hero' }).at(100, 160).size(28, 40).appendTo($.world);
    // Цель без физического тела — агент доходит точно до точки, не упираясь.
    $('<sprite>', { id: 'goal' }).at(520, 160).appendTo($.world);
});
